mapper.select:
SELECT b.id, b.serial_number, b.monomer_id monomerId, b.area_id areaId, w.id 'workShopId', gro.id 'groupId' , gro.`name` 'groupName', w.`name` 'workShopName', l.id 'productionLineId', l.`name` 'productionLineName', a.quantity 'quantity', 0 boolDrillEnum FROM `mes_building_nest_cut_machine_part_separate` a LEFT JOIN tech_machine_part b ON b.id = a.product_id LEFT JOIN mes_building_groups gro ON a.groups_id=gro.id AND gro.bool_delete_enum=0 LEFT JOIN mes_building_production_line l ON l.id = gro.production_line_id LEFT JOIN mes_building_workshop w ON w.id = gro.workshop_id WHERE a.bool_delete_enum = 0
AND a.nest_cut_id = #{cutId}
AND a.process_type = #{processType}
ORDER BY b.id

SELECT b.id, b.serial_number, b.monomer_id monomerId, w.id 'workShopId', gro.id 'groupId', gro.`name` 'groupName', w.`name` 'workShopName', l.id 'productionLineId', l.`name` 'productionLineName', a.task_quantity 'quantity', 1 boolDrillEnum FROM mes_building_task_process a LEFT JOIN tech_machine_part b ON b.id = a.product_id LEFT JOIN mes_building_groups gro ON a.groups_id = gro.id AND gro.bool_delete_enum = 0 LEFT JOIN mes_building_production_line l ON l.id = gro.production_line_id LEFT JOIN mes_building_workshop w ON w.id = gro.workshop_id LEFT JOIN mes_building_process process ON a.process_id=process.id WHERE a.bool_delete_enum = 0
AND a.nest_cut_plate_id = #{cutId}
AND process.type=8 ORDER BY b.id
